function tblLocal(){const o={},m2=x=>Math.round(x*100)/100,L=db.journal_lines||[];TBL_K.concat(TBL3,TBL4,TBL5).forEach(([k])=>o[k]=(db[k]||[]).length);o.saldo_tabungan=m2(typeof savTotal==="function"?savTotal():0);o.net_salary=m2((db.payrolls||[]).reduce((s,x)=>s+(+x.net_salary||0),0));o.debit=m2(L.reduce((s,x)=>s+(+x.debit||0),0));o.credit=m2(L.reduce((s,x)=>s+(+x.credit||0),0));o.principal=m2((db.loans||[]).reduce((s,x)=>s+(+x.principal||0),0));o.total_penjualan=m2((db.sales||[]).filter(x=>x.status==="posted").reduce((s,x)=>s+(+x.total||0),0));o.total_pembayaran=m2((db.payments||[]).filter(x=>x.status==="posted").reduce((s,x)=>s+(+x.amount||0),0));o.nilai_jaminan=m2((db.collaterals||[]).reduce((s,x)=>s+(+x.estimated_value||0),0));return o}
