function dvAturan(){const s=S.dvs;return`<h3>Aturan platform</h3><div class="card">${s?fld("dv-self","Admin BUMDes boleh membuat BUMDes baru sendiri",{t:"select",a:' onchange="devSelf(this.value)"',opts:opt([["1","Boleh"],["0","Hanya developer"]],x=>x,s.allow_self_create===false?"0":"1")}):`<p class="k">Tekan Muat ulang.</p>`}</div><h3>Catatan developer</h3><div class="card">${S.dva&&S.dva.length?S.dva.map(a=>`<div class="dv-lg">${dvFmt(a.at)} · ${esc(a.actor_email||"")} · <b>${esc(a.action)}</b>${a.detail?" · "+esc(a.detail):""}</div>`).join(""):`<p class="k">Belum ada catatan.</p>`}</div>`}
