 const form=pk?pick:ok?`<form onsubmit="entLogin();return false" novalidate><h1>Masuk</h1>${S.lgtg?`<div class="mk-tg" role="status"><b>Masuk ke ${esc(S.lgtg.name)}</b><button type="button" class="b s sm" onclick="lgTgOff()">Bukan BUMDes ini</button></div>`:""}<p class="k">Pengurus dan developer: pakai email. Nasabah: pakai nomor HP.</p>${fld("ln-em","Email atau nomor HP",{type:"text",a:' autocomplete="username" autocapitalize="off" spellcheck="false"',value:S.lgem||c.email||"",req:1})}<label for="ln-pw">Kata sandi atau PIN</label><div class="mk-pw"><input id="ln-pw" type="password" autocomplete="current-password" aria-required="true"><button type="button" id="ln-sh" class="b s sm" aria-pressed="false" onclick="lgPw()">Tampilkan</button></div><div class="fl"><button class="b" id="ln-go" type="submit"${busy}>${S.clb?"Memproses…":"Masuk"}</button></div><div class="fl"><button class="b s" type="button"${busy} onclick="cloudForgot('ln')">Lupa kata sandi pengurus</button></div><p class="k">Lupa PIN nasabah? Hubungi pengurus BUMDes. Masuk pertama kali butuh internet; setelah itu aplikasi tetap bisa dipakai offline di perangkat ini sampai Anda keluar.</p></form>`:`<h1>Masuk</h1><p>Koneksi Supabase belum diisi. Isi dulu di Setelan > Awan, atau pasang <b>SB_URL</b> dan <b>SB_KEY</b> di config.js.</p>`;
