 const sum=`<div class="card"><div class="kvg"><div class="kv"><span class="k">Koneksi</span><b>${ok?bd(0,c.fixed?"Terhubung (config.js)":"Terhubung","ok"):bd(0,"Belum diisi","wr")}</b></div><div class="kv"><span class="k">Akun</span><b>${on?esc(c.email||"Masuk"):"Belum masuk"}</b></div><div class="kv"><span class="k">BUMDes awan</span><b>${sel?esc(c.bumdes_name||"")+" · "+esc(c.role||""):"Belum dipilih"}</b></div><div class="kv"><span class="k">Sinkron</span><b>${sBd}</b></div></div>${t?`<p class="k" role="status">${esc(t.t)}${c.last?" · terakhir "+esc(String(c.last).replace("T"," ").slice(0,16)):""}</p>`:""}${next?`<p><b>Langkah berikut:</b> ${esc(next)}</p>`:""}${ok?`<div class="fl">${on?`<button class="b s" id="aw-out"${busy} onclick="cloudLogout()">Keluar</button>`:`<button class="b" id="aw-in" onclick="lgOpen()">Masuk ke akun awan</button>`}</div>`:""}</div>${S.clm?`<div class="card" role="status" aria-live="polite"><b>${esc(S.clm)}</b></div>`:""}`;
 const sync=on&&sel?`<h3>Sinkron</h3><div class="card"><div class="fl"><button class="b"${busy} onclick="cloudPush()">Simpan ke awan</button><button class="b s"${busy} onclick="cloudPullAsk()">Muat dari awan</button>${c.paused?`<button class="b s"${busy} onclick="askC('cloudForce','')">Timpa awan</button>`:""}</div>${fld("cl-auto","Sinkron otomatis dua arah",{t:"select",a:' onchange="cloudAutoSet(this.value)"',opts:opt([["0","Mati"],["1","Aktif"]],x=>x,c.auto?"1":"0")})}<div class="k">Aktif: perubahan dikirim beberapa detik setelah disimpan, dan data baru dari perangkat lain diambil saat aplikasi dibuka atau kembali online. Bila perangkat ini punya perubahan yang belum terkirim, sinkron dijeda agar tidak menimpa.</div></div>${c.role!=="pembaca"?sx("clh",!!(S.clh&&S.clh.length),"Riwayat cadangan","<div class=\"fl\"><button class=\"b s\""+busy+" onclick=\"cloudHist()\">Muat riwayat</button></div>"+(S.clh&&S.clh.length?`<div class="k">30 versi terakhir:</div>${S.clh.map(h=>`<div class="fl" style="justify-content:space-between;align-items:center;border-bottom:1px solid var(--bd,#8883);padding:6px 0"><span><b>Versi ${+h.version}</b><br><small>${esc(String(h.saved_at||"").replace("T"," ").slice(0,16))}${h.app_ver?" · app "+esc(h.app_ver):""}${+h.version===+c.ver?" · versi perangkat":""}</small></span><button class="b s sm"${busy} onclick="cloudRestore(${+h.version})">Pulihkan</button></div>`).join("")}`:"")):""}`:"";
 const kon=c.fixed?`<p>Proyek diatur di <b>config.js</b>: ${esc(c.url)}</p>`:`${SB_URL&&!SB_KEY?`<div class="k">SB_URL sudah ada di config.js tetapi SB_KEY (anon/publishable key) masih kosong. Isi di config.js agar koneksi otomatis, atau isi manual di bawah.</div>`:""}${fld("cl-url","Alamat proyek",{value:c.url||"",a:' autocomplete="off" inputmode="url" placeholder="https://xxxx.supabase.co"'})}${fld("cl-key","Anon key",{value:c.key||"",a:' autocomplete="off" spellcheck="false"'})}<div class="fl"><button class="b"${busy} onclick="cloudSave()">Simpan koneksi</button>${c.url?`<button class="b s" onclick="askC('cloudReset','')">Hapus pengaturan</button>`:""}</div><div class="k">Pakai anon/publishable key saja, bukan service_role atau secret. Pengaturan ini tidak ikut Export JSON.</div>`;
 const akun=on?`${fld("cl-p1","Kata sandi baru (min. 8)",{type:"password",a:' autocomplete="new-password"',value:""})}${fld("cl-p2","Ulangi kata sandi baru",{type:"password",a:' autocomplete="new-password"',value:""})}<div class="fl"><button class="b s"${busy} onclick="cloudChangePw()">Ganti kata sandi</button></div>`:"";
